let seed=DEMO.seed,isDemo=true,game=new Journey(features,DEMO),hasDelegated=false,epoch=0,request=null,history=[],quote=null,preview=null,comparison=null,attemptPath=null,stroke=null,tracers=null,flightPath=null,fieldEdit=null,selected=null,automaticMining=false,plannedOnward=false,lastProposal=null,lastSkyTime=-1,handleEditing=false,advance=false,recordedComparisons=[],previousAlternativePath=null,fuelRevisionPending=false,acceptedFuelRevision=false,uiError=false;
