function renderControls(){syncControls({view:game.view(),delegated:hasDelegated,request,pending:fuelRevisionPending,accepted:acceptedFuelRevision,quote,editing:handleEditing,error:uiError});}
function render(){const v=game.view();document.body.classList.toggle('arrived',v.phase==='arrived');for(const k of ['fuel','credits','lifetime']){$('#'+k).textContent=fmt(v.resources[k]);$('#budget-'+k).disabled=hasDelegated;}$('#budget-spend').textContent=hasDelegated?`${fmt(v.spent.fuel)} F · ${fmt(v.spent.credits)} C · ${fmt(v.spent.lifetime)} Y spent`:'Gross spending cap';$('#interrupt').disabled=!v.active&&!request;$('#undo').disabled=!v.canUndo;$('#phase-label').textContent=v.phase==='unknown'?'01 / AN UNFAMILIAR SKY':v.phase==='arrived'?'05 / HOME':v.target?'04 / ALONG THE COMPUTED PATH':v.report?'03 / SHAPE THE WAY FORWARD':'02 / EVIDENCE BECOMES ACTION';$('#scene-title').textContent=v.phase==='unknown'?'Find your way home.':v.phase==='arrived'?'We made it.':v.target?'A course we can follow.':'Now we can judge the move.';$('#scene-description').textContent=v.phase==='unknown'?(attemptPath?'Your push is kept as a free preview. Its homeward usefulness is still unknown.':'Drag outward from the ship to preview a push. Direction and length change the proposal.'):v.phase==='arrived'?`${fmt(v.time)} years traveled. Braking and arrival verified.`:v.target?'The faint old route stays beside the computed flight.':'The same sky now gives us a position and a home bearing.';
 $('#scene-caption').textContent=v.phase==='arrived'?'Arrival verified · inspect the receipt, rewind the field, or reset the sky':v.phase==='unknown'?'Home direction unknown · release leaves a free preview':quote?.kind.startsWith('gravity-')?'Bend gravity: drag the glowing handle. Watch the path and fuel change. Release applies.':v.target?`${fmt(v.time)} simulated years elapsed · Interrupt pauses at the current checkpoint`:'Position solved · Astra can now shape a gravity route home';$('#map-legend').innerHTML=attemptPath?`<span style="color:#e5bc8f">Your proposed push</span>${comparison?.sameState?'<span style="color:#c2d4ff">Astra’s alternative</span>':''}${previousAlternativePath?'<span style="color:#89a5c9">Earlier field preview</span>':''}<span style="color:#a8b2c5">Original motion</span>`:'';renderControls();
 if(lastSkyTime!==v.time){scene.setSky(game.sky());lastSkyTime=v.time;}const origin=v.calibration?.position,shipOffset=origin?game.shipVector(V.sub(v.position,origin)):[0,0,0];scene.set({view:v,preview,previewKind:quote?.kind,comparison,attemptPath,previousAlternativePath,stroke,selected,evidenceVisible:quote?.kind==='calibrate',fieldQuote:quote?.kind.startsWith('gravity-')?quote:null,handleY:fieldEdit?.handleY??0,tracers,flightPath,shipOffset,homeDirection:v.calibration?game.shipVector(V.scale(v.position,-1)):null,homeOrigin:origin?game.shipVector(V.scale(origin,-1)):null,homeDistance:v.homeDistance,asteroidOffset:v.report?game.shipVector(V.sub(v.report.position,origin)):null,fieldProgress:v.field?(v.time-v.field.start)/(v.field.until-v.field.start):null});
 $('#measurements').innerHTML=`<p>${v.calibration?`Four ranges solved position and bearings solved attitude. Held-out residual: ${v.calibration.heldOutResidual.toExponential(2)} ly in the ideal model.`:'Only bearings are available. Range, position and home direction remain unresolved.'}</p>`+v.observations.map(o=>`<p><b>${o.label}</b> · ${o.catalogueId?'Catalogue '+o.catalogueId:'unidentified'} · bearing [${o.bearing.map(n=>fmt(n,3)).join(', ')}]${o.range?' · '+fmt(o.range,5)+' ly':''}</p>`).join('');$('#ledger-count').textContent=`${v.ledger.length} actions`;$('#ledger').innerHTML=v.ledger.map(l=>`<tr><td>${esc(names[l.kind])}</td><td>${fmt(l.cost.fuel,3)} / ${fmt(l.reward.fuel,3)}</td><td>${fmt(l.cost.credits)} / ${fmt(l.reward.credits)}</td><td>${fmt(l.cost.lifetime,3)}</td></tr>`).join('');
 if(v.phase==='arrived')card({state:'ARRIVAL VERIFIED',title:'Home.',description:'The ship is inside the home region and at rest. The world can be quiet again.',metrics:[['Journey',`${fmt(v.time)} years`],['Fuel remaining',fmt(v.resources.fuel,2)],['Credits remaining',fmt(v.resources.credits)],['Lifetime remaining',fmt(v.resources.lifetime)]],actions:[['Inspect receipt',openDetails],['Explore again',()=>reset()]],evidence:`Final distance ${v.homeDistance.toExponential(3)} ly. Relative speed ${V.norm(v.velocity).toExponential(3)} ly/year. Gross spent ${fmt(v.spent.fuel,3)} fuel, ${fmt(v.spent.credits)} credits. Every reward came from the finite deposit and every debit appears in the ledger.`});
}
function brush(impulse,released){if(game.view().target||game.view().phase==='arrived')return;if(game.view().active||request)pause();try{stroke=impulse;const q=game.rawQuote({impulse});setQuote(q);if(released){game.rememberAttempt(q.id);attemptPath=game.preview(q.id,{frame:'ship',years:2}).proposed.path;say('Your push is kept as a free preview. Let’s find out whether it points us toward home.','PREVIEW · NO RESOURCES SPENT');render();}}catch(e){fail(e);}}
function establishBudget(){if(!hasDelegated){game.delegate(Object.fromEntries(['fuel','credits','lifetime'].map(k=>[k,Number($('#budget-'+k).value)])));hasDelegated=true;}else game.resume();}
function applyBrush(){if(!quote||quote.kind!=='experiment')return;const impulse=[...quote.detail.impulse];if(game.view().active||request)pause(true);try{establishBudget();const q=game.rawQuote({impulse});game.commit(q.id);game.pause();quote=null;preview=null;say('Impulse applied. The earlier stroke remains in the record; calibration will plan from the new velocity.','COMMITTED PHYSICS');render();}catch(e){fail(e);}}
function editField(speed,offset=[0,0,0],dy=0){try{const destination=fieldEdit?.destination??'home';let q=game.fieldQuote({destination,speed});const manual=V.norm(offset)>1e-10;if(manual)q=game.fieldQuote({destination,speed,centerShip:V.add(q.detail.centerShip,offset)});setQuote(q);fieldEdit.manual=manual;fieldEdit.handleY=dy;render();}catch(e){say(e.message,'FIELD PREVIEW');}}
async function releaseField(source){if(!quote?.kind.startsWith('gravity-'))return;const options={destination:quote.kind==='gravity-stop'?'asteroid':'home',speed:quote.detail.requestedSpeed,centerShip:[...quote.detail.centerShip]};if(source==='human')pause(true);try{establishBudget();const q=game.fieldQuote(options);setQuote(q);const status=game.assess(q.id);if(!status.affordable){pause(true);setQuote(game.fieldQuote(options));say(status.reason+' No field edit was committed. Drag back onto the guide or ask Astra to revise.','EDIT REJECTED');return;}automaticMining=options.destination==='asteroid';plannedOnward=automaticMining;const p=game.preview(q.id,{frame:'ship',years:2});flightPath=p.proposed.path;tracers=game.fieldTracers(q.id);game.commit(q.id);document.body.classList.remove('handle-busy');handleEditing=false;quote=null;preview=null;comparison=null;say(source==='astra'?'The handle is set. Now the force changes our velocity; no correction burn is being slipped in.':'Your field edit is applied. The same force now drives the ship and the tracers.','COMMITTED FIELD');render();return proceed(epoch);}catch(e){fail(e);}}
function candidates(){const list=[];for(const kind of game.options()){try{const q=game.quote(kind);list.push({...q,assessment:game.assess(q.id)});}catch{}}return list;}
function makeRequest(message,qs){const v=game.view(),a=game.attempt();return {requestId:crypto.randomUUID(),revision:v.revision,message,history:history.slice(-16),observation:{phase:v.phase,delegated:v.active,resources:v.resources,budgetRemaining:Object.fromEntries(Object.keys(v.budget).map(k=>[k,Math.max(0,v.budget[k]-v.spent[k])])),preference:v.preference,landmarks:v.observations,navigation:v.calibration?{distance:v.homeDistance,speed:V.norm(v.velocity),target:v.target?.name??'none',remaining:v.target?.remaining??0,calibrationResidual:v.calibration.residual}:null,asteroid:v.report?{relativePosition:V.sub(v.report.position,v.position),velocity:v.report.velocity,radiusKm:v.report.radiusKm,operationRadiusLy:v.report.operationRadiusLy,spinPeriodHours:v.report.spinPeriodHours,grossFuel:v.deposit.fuel,grossCredits:v.deposit.credits,extractionFuel:3,extractionCredits:2,extractionYears:2,reportCreditsPaid:3}:null,attempt:a?{impulse:a.impulse,fuel:a.cost.fuel,years:2,committed:a.committed}:null},choices:qs.map(q=>{const pr=game.preview(q.id,{frame:'ship',years:2}),cmp=(q.kind.startsWith('gravity-')||q.kind.startsWith('launch-'))?game.compareAttempt(q.id,{years:2}):null;return {id:q.id,kind:q.kind,cost:q.cost,summary:q.detail.summary.slice(0,400),years:q.detail.years??0,reserve:q.detail.reserve??0,affordable:q.assessment.affordable,reason:q.assessment.reason,evidence:{impulse:q.detail.impulse??[0,0,0],gravityBefore:q.detail.gravityBefore??0,gravityAfter:q.detail.gravityAfter??0,gravityDuration:q.detail.gravityDuration??0,braking:q.detail.braking??0,speed:q.detail.speed??0,endpointSeparation:pr?V.norm(V.sub(pr.current.p,pr.proposed.p)):0,grossFuel:q.reward.fuel,grossCredits:q.reward.credits},field:q.kind.startsWith('gravity-')?{centerShip:q.detail.centerShip,duration:q.detail.duration,strength:q.detail.strength,miss:q.detail.miss,fullTripFuel:q.detail.miningComparison?.totalFuelSpent??q.cost.fuel+q.detail.braking,onwardMode:q.kind==='gravity-stop'?'direct-slow':'none'}:null,comparison:cmp?.sameState?{years:cmp.years,attemptFuel:cmp.attemptFuel,alternativeFuel:cmp.alternativeFuel,attemptHomeProgress:cmp.attemptHomeProgress,alternativeHomeProgress:cmp.alternativeHomeProgress}:null};})};}
async function decide(message='Continue the delegated plan from the supplied evidence.',observeOnly=false){const token=epoch;if(!game.view().active&&!observeOnly)return;const qs=candidates();if(!qs.length)return fail(Error('No supported affordable continuation; reset or revise the current plan.'));const body=makeRequest(message,qs),ctrl=new AbortController();request=ctrl;render();try{let res;for(let retry=0;retry<21;retry++){res=await fetch('/api/journey',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:ctrl.signal});if(res.status!==409)break;await new Promise(r=>setTimeout(r,5000));if(token!==epoch)return;}const data=await res.json();if(token!==epoch||game.revision!==body.revision)return;if(!res.ok)throw Error(data.message||'Live Astra unavailable');if(data.requestId!==body.requestId||data.revision!==body.revision||data.model!=='gpt-6-astra')throw Error('Stale model reply rejected');request=null;const p=data.proposal;say(p.summary);if(observeOnly){if(p.preference!=='keep')game.preference(p.preference);fuelRevisionPending=false;render();return;}if(p.preference!=='keep'&&p.preference!==game.view().preference){const before=game.view().target?null:(lastProposal?.kind.startsWith('gravity-')?lastProposal:qs.find(q=>q.kind==='gravity-home'));if(before){const old=game.fieldQuote({destination:before.kind==='gravity-stop'?'asteroid':'home',speed:before.detail.requestedSpeed});previousAlternativePath=game.preview(old.id,{frame:'ship',years:2}).proposed.path;}game.preference(p.preference);if(before){const after=game.quote(before.kind);const change={kind:before.kind,before:{fuel:before.cost.fuel+before.detail.braking,years:before.detail.years,speed:before.detail.requestedSpeed??before.detail.speed,center:before.detail.centerShip},after:{fuel:after.cost.fuel+after.detail.braking,years:after.detail.years,speed:after.detail.requestedSpeed??after.detail.speed,center:after.detail.centerShip}};recordedComparisons.push(change);setQuote(after);say(`Changed the control: ${fmt(change.before.fuel,2)} → ${fmt(change.after.fuel,2)} fuel including this leg’s brake; ${fmt(change.before.years)} → ${fmt(change.after.years)} years. The field and route preview now use the revised setting.`,'COMPUTED CHANGE');}return decide('The human priority is now applied. Continue with the newly quoted lower-cost control.');}
 if(p.actionId===null){fuelRevisionPending=false;pause(true);return;}const chosen=qs.find(q=>q.id===p.actionId);if(!chosen||!chosen.assessment.affordable)throw Error('Unsupported or unaffordable action rejected');fuelRevisionPending=false;setQuote(chosen);if(chosen.kind.startsWith('gravity-'))return await astraField(chosen,token);return await schedule(chosen,token);
 }catch(e){if(e.name!=='AbortError'&&token===epoch)fail(e);}finally{if(request===ctrl)request=null;render();}}
async function waitPreview(seconds,token){advance=false;const start=performance.now();while(!advance&&performance.now()-start<seconds*1000){if(token!==epoch||!game.view().active)return false;$('#execution-notice').textContent=`${quote?.kind.startsWith('gravity-')?'Astra moves the handle':'Next action'} in ${Math.max(0,Math.ceil(seconds-(performance.now()-start)/1000))} s · Interrupt to revise`;await new Promise(r=>setTimeout(r,80));}$('#execution-notice').textContent='';return token===epoch&&game.view().active;}
async function astraField(q,token){await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(token!==epoch||!game.view().active)return;if(!await waitPreview(20,token))return;document.body.classList.add('handle-busy');const target=q.detail.requestedSpeed,begin=Math.min(.065,target+.018);fieldEdit={destination:q.kind==='gravity-stop'?'asteroid':'home',speed:begin};say('We can reshape the field here. I’m moving the same handle you can drag.','DELEGATED FIELD CONTROL');const duration=scene.reduced?0:3000,start=performance.now();do{if(token!==epoch||!game.view().active)return;const t=duration?Math.min(1,(performance.now()-start)/duration):1;editField(begin+(target-begin)*(t*t*(3-2*t)));if(t>=1)break;await new Promise(r=>setTimeout(r,90));}while(true);if(token===epoch)return releaseField('astra');}
async function schedule(q,token=epoch){if(token!==epoch||!game.view().active)return;setQuote(q);const bending=q.kind==='coast'&&game.view().field&&game.view().time<game.view().field.until-1e-9;const seconds=q.kind==='coast'?(bending?(scene.reduced?.5:.75):1):q.kind==='calibrate'?4:q.kind==='brake'?2:2.5;if(!await waitPreview(seconds,token))return;try{game.commit(q.id);quote=null;preview=null;comparison=null;if(q.kind==='calibrate'){say('Four independent landmarks agree with the recovered position. Your push is still on the same starting state; now we can measure its homeward effect.','MEASURED & SOLVED');card({state:'POSITION VERIFIED',title:'Now we know where we are.',description:'Eight landmarks agree. Astra is comparing the available routes within your budget.',metrics:[['Investigation paid','6 credits'],['Fuel / time spent','0 / 0']],evidence:'Four observations solved position and orientation; four held-out landmarks verified them. The home bearing is now supported by that solution.'});}if(q.kind==='extract'){say('The finite patch is exhausted: 32 fuel and 8 credits recovered, after paying 3 fuel, 2 credits and 2 years.','VERIFIED EXTRACTION');if(plannedOnward){game.preference('less-fuel');plannedOnward=false;}}render();if(game.view().phase==='arrived'){say('We made it. Position and speed both passed the arrival check.','VERIFIED ARRIVAL');return;}return proceed(token);}catch(e){fail(e);}}
async function proceed(token=epoch){if(token!==epoch||!game.view().active)return;const v=game.view(),opts=game.options();if(v.target)return schedule(game.quote(opts[0]),token);if(v.phase==='at-stop'&&automaticMining)return schedule(game.quote('extract'),token);if(v.phase==='mined'){const q=game.quote('launch-home',{speed:.025});return schedule(q,token);}return decide();}
function takeHelm(message='Get us home directly. You drive. Use the preserved push preview as a reference, propose an affordable gravity edit, and keep the asteroid stop outside this primary run unless I ask for it.'){if(game.view().active||request)pause(true);try{uiError=false;establishBudget();render();decide(message);}catch(e){fail(e);}}
function send(message){if(game.view().phase==='arrived')return;const fuel=/less fuel/i.test(message);if(fuel&&fuelRevisionPending)return;say(message,'YOU','user');if(game.view().active||request)pause(true);fuelRevisionPending=fuel;uiError=false;render();if(!hasDelegated)return decide(message,true);takeHelm(message);}
$('#delegate').onclick=()=>takeHelm();$('#interrupt').onclick=()=>{pause(true);say('Paused. The original gross-spend permission is intact; pending replies and actions are invalid.','HELM INTERRUPTED');};$('#chat-form').onsubmit=e=>{e.preventDefault();const m=$('#message').value.trim();if(m){$('#message').value='';send(m);}};function requestLessFuel(){send('Use less fuel and keep driving.');}revisionButton.onclick=requestLessFuel;$('#skip-stop').onclick=()=>send('Skip the asteroid stop and take us home.');
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&(game.view().active||request)){$('#interrupt').click();}});
$('#brush-mode').onclick=()=>setMode('brush');$('#look-mode').onclick=()=>setMode('look');function setMode(m){scene.setMode(m);for(const id of ['brush','look']){$('#'+id+'-mode').classList.toggle('active',id===m);$('#'+id+'-mode').setAttribute('aria-pressed',String(id===m));}}$('#recenter').onclick=()=>scene.recenter();
function openDetails(){$('#detail-drawer').hidden=false;$('#details-toggle').setAttribute('aria-expanded','true');}$('#details-toggle').onclick=openDetails;$('#close-details').onclick=()=>{$('#detail-drawer').hidden=true;$('#details-toggle').setAttribute('aria-expanded','false');};
$('#undo').onclick=()=>{pause();try{game.undo();acceptedFuelRevision=false;recordedComparisons=[];previousAlternativePath=null;flightPath=null;tracers=null;comparison=null;history=[];say('Rewound the field edit and every later checkpoint. Time, resources, deposit and ledger are restored together.','UNDO · COMPLETE STATE RESTORED');render();setQuote(game.fieldQuote({destination:automaticMining&&game.view().report?'asteroid':'home'}));}catch(e){fail(e);}};
function reset(random=false,demo=isDemo){pause();isDemo=demo;if(random)seed=Math.floor(Math.random()*2**32);else if(demo)seed=DEMO.seed;game=new Journey(features,demo?{...DEMO,seed}:{seed});hasDelegated=false;fuelRevisionPending=false;acceptedFuelRevision=false;uiError=false;history=[];quote=null;preview=null;comparison=null;attemptPath=null;stroke=null;tracers=null;flightPath=null;fieldEdit=null;selected=null;automaticMining=false;plannedOnward=false;lastProposal=null;lastSkyTime=-1;recordedComparisons=[];previousAlternativePath=null;$('#conversation').replaceChildren();for(const [k,n] of Object.entries(demo?{fuel:35,credits:15,lifetime:550}:{fuel:75,credits:20,lifetime:900}))$('#budget-'+k).value=n;$('#preset-label').textContent=demo?'Comparison preset · 35 fuel / 15 credits / 550 years':'Random run · original 100 fuel / 30 credits / 1,000 years';say('I’m here. Try a direction, then we can work out where home is.','ASTRA · READY');scene.recenter();card({state:'YOUR FIRST MOVE',title:'A direction, not yet a route.',description:'Drag outward from the ship. Direction and length set the push; release keeps a free preview.',evidence:'Preview a push: drag outward from the ship. Move view rotates the camera. Release keeps a free preview; applying it spends the quote.'});render();}
$('#reset').onclick=()=>reset();$('#random-sky').onclick=()=>reset(true,false);$('#demo-sky').onclick=()=>reset(false,true);$('#export-ledger').onclick=()=>{const blob=new Blob([JSON.stringify({model:'brush-gravity-comparison-v1',...game.view(),attempt:game.attempt(),humanRevisions:recordedComparisons},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='brush-journey-record.json';a.click();URL.revokeObjectURL(url);};render();
